/* glossary.js -- universal inline-term glossary, sourced from the project
 * owner's OpenEvidence export (Glossary.md). Every entry's `keys` are the
 * exact-match phrases (case-insensitive unless the key is a short ALL-CAPS
 * acronym, matched case-sensitively) that js/app.js's auto-linker looks for
 * in rendered content and wraps as a `.term` glossary popover -- the SAME
 * definition appears everywhere the term is mentioned, across every module,
 * not just the module it's nominally filed under below.
 *
 * `def` is the core definition shown by default; `more` (when present) is
 * the added clinical detail (mechanism/pitfall/number/decision), hidden
 * behind a "Read more" toggle in the popover so short and long entries both
 * stay readable at a glance. No citations are embedded (verify doses/claims
 * locally, per this project's standing convention). */
window.JEFFENT = window.JEFFENT || {
  modules: [],
  register: function (mod) { this.modules.push(mod); },
  get: function (id) { return this.modules.find(function (m) { return m.id === id; }); }
};

window.JEFFENT.glossary = [
  { term: "Otoscopy", keys: ["Otoscopy"], def: "Examination of the ear canal and tympanic membrane using an otoscope. The pinna is pulled up-and-back in adults and down-and-back in young children to straighten the cartilaginous canal; systematically note TM color, translucency, contour, and mobility. Pneumatic otoscopy is the most useful bedside test for a middle-ear effusion.", more: "use the largest speculum the canal will accept and a tight air seal — a normal drum moves briskly to insufflation, while sluggish or absent movement is the single most reliable sign of effusion." },
  { term: "Tympanic membrane (TM)", keys: ["Tympanic membrane (TM)", "Tympanic membrane"], def: "The eardrum; a three-layered membrane separating the external canal from the middle ear, divided into the taut pars tensa and lax pars flaccida.", more: "its outer squamous layer migrates laterally and outward from the umbo, giving the TM a self-cleaning conveyor that clears keratin — failure of this migration underlies retraction-pocket cholesteatoma." },
  { term: "Cone of light", keys: ["Cone of light"], def: "The triangular reflection of otoscope light off the antero-inferior TM; loss or fragmentation is an early clue to effusion or retraction.", more: "it is a nonspecific finding — a normal drum can lose the reflex with speculum angle alone, so never diagnose pathology on the cone of light in isolation." },
  { term: "Umbo", keys: ["Umbo"], def: "The central, most depressed point of the TM, marking the tip of the malleus handle (manubrium).", more: "it is the point of maximal TM displacement during sound transmission and the fulcrum of the ossicular lever." },
  { term: "Pars tensa", keys: ["Pars tensa"], def: "The larger, taut lower portion of the TM, stiffened by the fibrous middle layer (annulus); the main sound-conducting region and site of most simple perforations.", more: "central (pars tensa) perforations sparing the annulus are \"safe,\" whereas marginal perforations reaching the annulus carry cholesteatoma risk." },
  { term: "Pars flaccida", keys: ["Pars flaccida"], def: "The smaller, lax upper portion lacking the fibrous middle layer; prone to inward retraction and the classic site of attic cholesteatoma.", more: "it is easily hidden by the superior canal wall — failure to examine the attic is a classic reason early cholesteatoma is missed." },
  { term: "Weber test", keys: ["Weber test"], def: "512 Hz fork on the vertex; lateralizes to the affected ear in conductive loss and to the better ear in sensorineural loss.", more: "a conductive gap of roughly ≥10 dB is generally needed before lateralization becomes reliable." },
  { term: "Rinne test", keys: ["Rinne test"], def: "Compares air conduction with bone conduction; AC > BC (positive) is normal/sensorineural, BC > AC (negative) indicates conductive loss.", more: "a severe unilateral SNHL can give a false-negative Rinne when the fork is heard by the opposite cochlea via bone (the \"false negative\" of profound SNHL) — always pair with Weber." },
  { term: "Air-bone gap", keys: ["Air-bone gap"], def: "The difference between air- and bone-conduction thresholds; localizes loss to a conductive component.", more: "a gap >30–40 dB with an intact drum suggests ossicular discontinuity, whereas otosclerosis typically produces a smaller gap that is largest at low frequencies." },
  { term: "Audiogram", keys: ["Audiogram"], def: "Graph of hearing thresholds (dB) across frequencies (Hz).", more: "normal is ≤25 dB HL; mild 26–40, moderate 41–55, moderately severe 56–70, severe 71–90, and profound >90 dB HL." },
  { term: "Tympanometry", keys: ["Tympanometry"], def: "Objective measure of TM mobility and middle-ear pressure; Type A normal, Type B flat, Type C negative pressure.", more: "Type C reflects middle-ear pressure more negative than about −150 to −200 daPa; a Type B with normal canal volume implies effusion, while a Type B with high volume implies perforation or a patent tube." },
  { term: "Conductive hearing loss", keys: ["Conductive hearing loss"], def: "Impaired transmission through external/middle ear (cerumen, effusion, perforation, otosclerosis, ossicular problems).", more: "the middle ear normally provides ~30 dB of impedance matching via the TM-to-oval-window area ratio and ossicular lever, so its loss defines the maximum conductive gap." },
  { term: "Sensorineural hearing loss (SNHL)", keys: ["Sensorineural hearing loss (SNHL)", "Sensorineural hearing loss", "SNHL"], def: "Cochlear hair-cell or auditory-nerve dysfunction; generally permanent.", more: "an interaural asymmetry of ≥15 dB at 3 kHz (or ≥15% word-recognition difference) should prompt MRI to exclude a retrocochlear lesion." },
  { term: "Referred otalgia", keys: ["Referred otalgia"], def: "Ear pain with a normal ear exam, transmitted via CN V, VII, IX, X, and C2–C3.", more: "in an adult smoker/drinker with normal otoscopy, referred otalgia mandates full mucosal exam and flexible laryngoscopy — a normal ear does not exclude an aerodigestive malignancy." },
  { term: "Flexible nasolaryngoscopy", keys: ["Flexible nasolaryngoscopy"], def: "Transnasal fiberoptic exam of the nasal cavity, nasopharynx, pharynx, and larynx in the awake patient.", more: "it is the standard first study for any hoarseness persisting beyond 3–4 weeks to directly visualize vocal-fold mobility and lesions." },
  { term: "Anterior rhinoscopy", keys: ["Anterior rhinoscopy"], def: "Speculum-and-light inspection of the anterior septum, turbinates, and mucosa.", more: "it visualizes only the anterior third of the nasal cavity — posterior masses, choanal lesions, and the OMC require endoscopy, so a normal rhinoscopy does not exclude posterior pathology." },
  { term: "Cricothyroid membrane", keys: ["Cricothyroid membrane"], def: "The membrane between thyroid and cricoid cartilages; the access point for emergency surgical airway.", more: "it lies roughly 1–1.5 cm below the thyroid notch and is ~10 mm tall — incise vertically through skin, then horizontally through the membrane to avoid the cricothyroid vessels superiorly." },
  { term: "HINTS exam", keys: ["HINTS exam"], def: "Head-Impulse, Nystagmus, Test of Skew battery for acute continuous vertigo.", more: "it is valid only in acute vestibular syndrome with ongoing nystagmus — applying it to episodic or resolved vertigo is a misuse, and a \"normal\" head impulse in a patient with acute vertigo is worrisome for stroke." },
  { term: "SBAR", keys: ["SBAR"], def: "Situation, Background, Assessment, Recommendation handoff format.", more: "airway or hemodynamic instability is stated in the first sentence so the receiver can act before the full narrative." },
  { term: "SPIKES", keys: ["SPIKES"], def: "Six-step bad-news protocol: Setting, Perception, Invitation, Knowledge, Emotions, Strategy.", more: "the \"warning shot\" precedes disclosure and empathic acknowledgment of emotion precedes any discussion of the plan." },
  { term: "External auditory canal (EAC)", keys: ["External auditory canal (EAC)", "External auditory canal", "EAC"], def: "Outer third cartilaginous (cerumen, hair), inner two-thirds bony and thin-skinned.", more: "the adult canal is ~2.5 cm long with an S-shaped course; the fissures of Santorini at the cartilage-bone junction are the route by which necrotizing otitis externa breaches to the skull base." },
  { term: "Ossicles", keys: ["Ossicles"], def: "Malleus, incus, stapes lever chain matching air-to-fluid impedance.", more: "the ossicular lever plus the TM-to-footplate area ratio (~17–20:1) together provide ~25–30 dB of gain; the long process of the incus is the most vascularly vulnerable and first to erode." },
  { term: "Tensor tympani", keys: ["Tensor tympani"], def: "Small middle-ear muscle running from the cartilaginous Eustachian tube to the malleus neck; innervated by CN V3 (mandibular branch of the trigeminal nerve).", more: "it co-contracts with the stapedius in the acoustic (stapedial) reflex, stiffening the ossicular chain to dampen transmission of loud sound — its tendon is also a landmark during middle-ear and cochlear-implant surgery." },
  { term: "Stapedius", keys: ["Stapedius"], def: "Smallest skeletal muscle in the body, running from the pyramidal eminence to the stapes neck; innervated by CN VII (facial nerve).", more: "its reflex contraction to loud sound stiffens the stapes and is the basis of stapedial (acoustic) reflex testing — an absent reflex with an intact-appearing TM can point to a CN VII lesion or otosclerosis fixing the stapes." },
  { term: "Eustachian tube", keys: ["Eustachian tube"], def: "Connects middle ear to nasopharynx, equalizing pressure and draining secretions.", more: "it opens actively via tensor veli palatini on swallowing/yawning; the child's shorter, more horizontal tube explains the peak AOM incidence at 6–18 months." },
  { term: "Cochlea", keys: ["Cochlea"], def: "Spiral organ of hearing; organ of Corti transduces along a tonotopic map.", more: "it makes ~2.5–2.75 turns, with high frequencies at the base and low at the apex — the basis for frequency-specific cochlear implant electrode mapping." },
  { term: "Vestibule and semicircular canals", keys: ["Vestibule and semicircular canals", "Semicircular canals"], def: "Otolith organs sense linear acceleration; three canals sense angular rotation.", more: "the canals are paired in push-pull coplanar sets, so a head turn excites one side and inhibits the other — the substrate for the vestibulo-ocular reflex tested by head impulse." },
  { term: "Chorda tympani", keys: ["Chorda tympani"], def: "CN VII branch carrying anterior two-thirds tongue taste and submandibular/sublingual secretomotor fibers.", more: "it crosses the middle ear without bony cover, so it is readily stretched or divided in tympanoplasty — warn patients of transient metallic taste." },
  { term: "Cerumen impaction", keys: ["Cerumen impaction"], def: "Symptomatic or view-obstructing wax, not merely visible wax.", more: "irrigation is contraindicated with a non-intact or uncertain TM, prior ear surgery, or diabetes — use cerumenolytics or manual removal instead." },
  { term: "Otitis externa", keys: ["Otitis externa"], def: "Diffuse canal infection (\"swimmer's ear\"), classically Pseudomonas or Staph.", more: "topical drops achieve canal concentrations far exceeding MIC, so first-line therapy is topical (± wick), not oral antibiotics, in the uncomplicated case." },
  { term: "Acute otitis media (AOM)", keys: ["Acute otitis media (AOM)", "Acute otitis media", "AOM"], def: "Symptomatic middle-ear infection with a bulging, poorly mobile TM and effusion.", more: "bulging of the TM is the key diagnostic sign — bacteria are recoverable from ~80% of bulging drums, whereas redness without bulging warrants AOM diagnosis in only ~25% of cases." },
  { term: "Otitis media with effusion (OME)", keys: ["Otitis media with effusion (OME)", "Otitis media with effusion", "OME"], def: "Middle-ear fluid behind an intact TM without acute infection.", more: "effusion persisting ≥3 months is chronic OME and warrants audiometry and consideration of tympanostomy tubes, particularly with hearing loss or speech delay." },
  { term: "Cholesteatoma", keys: ["Cholesteatoma"], def: "Expanding keratinizing squamous sac that erodes bone via osteolytic enzymes.", more: "painless, foul otorrhea unresponsive to drops with an attic crust is cholesteatoma until proven otherwise — definitive treatment is surgical, and drops alone are a delay trap." },
  { term: "Prussak's space", keys: ["Prussak's space"], def: "Epitympanic recess bounded by pars flaccida laterally and malleus neck medially.", more: "it is the earliest site of attic cholesteatoma and drains poorly, explaining why disease accumulates here before becoming otoscopically obvious." },
  { term: "Necrotizing (malignant) otitis externa", keys: ["Necrotizing (malignant) otitis externa", "Malignant otitis externa"], def: "Skull-base osteomyelitis, almost always Pseudomonas, in diabetics/immunocompromised.", more: "pain out of proportion plus granulation at the bony-cartilaginous junction is the hallmark; CN VII palsy is the first cranial neuropathy, and treatment is weeks of IV antipseudomonal therapy — not topical drops." },
  { term: "Otosclerosis", keys: ["Otosclerosis"], def: "Bony remodeling fixing the stapes footplate, causing progressive conductive loss.", more: "autosomal dominant with ~40% penetrance, typically presenting in the 20s–40s, often bilateral, and accelerated by pregnancy." },
  { term: "Carhart notch", keys: ["Carhart notch"], def: "Artifactual bone-conduction dip at ~2000 Hz in otosclerosis.", more: "it reflects loss of the ossicular resonance contribution to bone conduction and reverses after successful stapedectomy." },
  { term: "Ossicular discontinuity", keys: ["Ossicular discontinuity"], def: "Break in the chain (usually incudostapedial joint) from trauma/infection/cholesteatoma.", more: "produces a large conductive gap (often >30–40 dB) with a hypermobile Type Ad tympanogram — the mechanical opposite of the stiff As pattern of otosclerosis." },
  { term: "BPPV", keys: ["BPPV"], def: "Brief positional vertigo from otoconia in a semicircular canal (usually posterior).", more: "posterior-canal BPPV accounts for ~80–90% of cases; vertigo lasts seconds with a characteristic latency and fatigability, and hearing is normal." },
  { term: "Dix-Hallpike maneuver", keys: ["Dix-Hallpike maneuver"], def: "Provocative test hanging the head with the affected ear down.", more: "it elicits an upbeat-torsional nystagmus with a 1–5 second latency that fatigues — an immediate, non-fatiguing, or direction-changing nystagmus suggests a central cause." },
  { term: "Epley maneuver", keys: ["Epley maneuver"], def: "Repositioning sequence returning otoconia from the posterior canal to the utricle.", more: "a single maneuver resolves BPPV in roughly 80% of patients, with repeat treatment for persistent cases." },
  { term: "Vestibular neuritis", keys: ["Vestibular neuritis"], def: "Acute constant vertigo lasting days from vestibular nerve inflammation.", more: "HINTS is reassuring-peripheral and hearing is normal — any new hearing loss reclassifies it as labyrinthitis and any central HINTS sign mandates stroke workup." },
  { term: "Ménière's disease", keys: ["Ménière's disease"], def: "Endolymphatic hydrops causing episodic vertigo with fluctuating low-mid SNHL, tinnitus, fullness.", more: "diagnosis requires ≥2 spontaneous vertigo episodes lasting 20 minutes to 12 hours with audiometrically documented low-to-mid SNHL in the affected ear." },
  { term: "Labyrinthine fistula", keys: ["Labyrinthine fistula"], def: "Abnormal opening into the inner ear, classically lateral semicircular canal eroded by cholesteatoma.", more: "a positive fistula test (pressure-induced vertigo/nystagmus on tragal pressure) localizes the erosion and predicts intraoperative findings." },
  { term: "Vestibular schwannoma (acoustic neuroma)", keys: ["Vestibular schwannoma (acoustic neuroma)", "Vestibular schwannoma", "acoustic neuroma"], def: "Benign vestibular-nerve Schwann-cell tumor in the IAC.", more: "it presents with asymmetric SNHL and unilateral tinnitus rather than true vertigo, and sudden SNHL can be its first sign — MRI of the IACs with contrast is the diagnostic test." },
  { term: "Mastoidectomy", keys: ["Mastoidectomy"], def: "Removal of mastoid air cells and disease.", more: "canal-wall-up preserves anatomy but carries higher recurrence and usually a planned second-look at ~9–12 months, whereas canal-wall-down lowers recurrence at the cost of a lifelong cavity requiring cleaning." },
  { term: "Tympanoplasty", keys: ["Tympanoplasty"], def: "TM repair (± ossicular reconstruction), grafted with fascia or cartilage-perichondrium.", more: "graft take rates are ~85–90%; cartilage grafting is favored for large/revision perforations or Eustachian tube dysfunction because of its resistance to reperforation." },
  { term: "Facial recess", keys: ["Facial recess"], def: "Window bounded by the facial nerve medially, chorda tympani laterally, incus buttress superiorly.", more: "opening it (posterior tympanotomy) gives mastoid access to the round window for cochlear implant electrode insertion while keeping the nerve under direct view." },
  { term: "Stylomastoid foramen", keys: ["Stylomastoid foramen"], def: "Opening at the skull base, between the styloid and mastoid processes, where the facial nerve (CN VII) exits the temporal bone to enter the parotid region.", more: "it is the classic landmark for identifying and preserving the main trunk of the facial nerve during parotidectomy and mastoid surgery." },
  { term: "Cochlear implant", keys: ["Cochlear implant"], def: "Bypasses hair cells to stimulate the auditory nerve directly.", more: "candidacy is severe-to-profound SNHL with limited aided benefit, conventionally aided sentence-recognition scores at or below ~50–60% in the ear to be implanted." },
  { term: "Turbinates", keys: ["Turbinates", "Concha", "Conchae"], def: "Three paired projections (inferior, middle, superior) that warm, humidify, and direct airflow.", more: "the inferior turbinate is the primary regulator of nasal resistance via venous sinusoid engorgement, cycling side-to-side every few hours (the nasal cycle) — the reason unilateral congestion often alternates." },
  { term: "Ostiomeatal complex (OMC)", keys: ["Ostiomeatal complex (OMC)", "Ostiomeatal complex", "OMC"], def: "Common drainage funnel in the middle meatus for frontal, anterior ethmoid, and maxillary sinuses.", more: "because all three share this channel, a single point of OMC obstruction can cause disease in three sinuses at once — the central rationale for FESS." },
  { term: "Uncinate process", keys: ["Uncinate process"], def: "Sickle-shaped bony flap forming the ethmoid infundibulum with the bulla.", more: "its free edge lies just anterior to the lamina papyracea, so uncinectomy carried too laterally is a classic route to orbital entry." },
  { term: "Lamina papyracea", keys: ["Lamina papyracea"], def: "Paper-thin medial orbital wall between ethmoid sinus and orbit.", more: "a breach with orbital fat prolapse plus periorbital ecchymosis intraoperatively signals penetration — never grasp herniated fat (risk of medial rectus avulsion and diplopia)." },
  { term: "Sphenoethmoidal recess", keys: ["Sphenoethmoidal recess"], def: "Drainage site of the sphenoid sinus, medial to the superior turbinate.", more: "the natural sphenoid ostium sits ~7 cm from the nasal sill at ~30° from the floor, medial to the superior turbinate — the landmark for safe sphenoidotomy." },
  { term: "Kiesselbach's plexus (Little's area)", keys: ["Kiesselbach's plexus (Little's area)", "Kiesselbach's plexus", "Little's area"], def: "Anterior septal anastomosis of four arteries.", more: "it is the source of >90% of epistaxis and the target of first-line anterior pressure/cautery." },
  { term: "Sphenopalatine artery", keys: ["Sphenopalatine artery"], def: "Terminal maxillary artery branch supplying the posterior nasal cavity.", more: "it is the source of most posterior epistaxis and the target of endoscopic ligation when packing fails — it exits the sphenopalatine foramen at the posterior attachment of the middle turbinate." },
  { term: "Keros classification", keys: ["Keros classification"], def: "Grades olfactory-fossa depth (I–III) by lateral lamella length.", more: "Keros III (lateral lamella 7–16 mm) carries the highest risk of cribriform/skull-base injury and CSF leak — flagged preoperatively on coronal CT." },
  { term: "Concha bullosa", keys: ["Concha bullosa"], def: "Pneumatized middle turbinate.", more: "usually incidental, but a large one narrows the OMC and can be mistaken for a polyp — resect the lateral lamella while preserving the medial to keep the turbinate as a landmark." },
  { term: "Haller cells", keys: ["Haller cells"], def: "Infraorbital ethmoid cells along the orbital floor near the maxillary ostium.", more: "they narrow the maxillary infundibulum and bring the orbital floor into the surgical field, contributing to recurrent maxillary disease." },
  { term: "Onodi cells", keys: ["Onodi cells"], def: "Most posterior ethmoid cells pneumatizing superolateral to the sphenoid.", more: "the optic nerve and carotid may be dehiscent within an Onodi cell — mistaking it for the sphenoid on CT is a classic setup for optic nerve injury." },
  { term: "Orbit", keys: ["Orbit"], def: "The bony eye socket, formed by seven bones and separated from the ethmoid and maxillary sinuses by paper-thin walls (the lamina papyracea medially, the orbital floor inferiorly).", more: "its thin sinus-facing walls are the route by which sinus infection or surgical instrumentation can breach into orbital fat, causing preseptal or postseptal cellulitis, or orbital compartment syndrome." },
  { term: "Optic nerve", keys: ["Optic nerve"], def: "CN II; carries visual information from the retina to the brain, running along the superolateral wall of the sphenoid sinus (sometimes within a dehiscent Onodi cell) before entering the optic canal.", more: "its close, sometimes bony-deficient relationship to the sphenoid and posterior ethmoid sinuses makes it vulnerable during posterior sinus and skull-base surgery — injury causes sudden, often irreversible vision loss." },
  { term: "Carotid artery", keys: ["Carotid artery", "Internal carotid artery"], def: "Major artery supplying the brain and orbit; its petrous and cavernous segments run immediately lateral to the sphenoid sinus, sometimes with a dehiscent bony covering.", more: "a dehiscent or medially bulging carotid within the sphenoid sinus is a critical finding on preoperative CT — inadvertent injury during sphenoid or skull-base surgery causes catastrophic hemorrhage." },
  { term: "Cavernous sinus", keys: ["Cavernous sinus"], def: "Paired venous channel lateral to the sphenoid sinus and pituitary, through which the internal carotid artery and cranial nerves III, IV, V1, V2, and VI travel.", more: "its intimate relationship to the sphenoid sinus means posterior sinus infection or tumor can spread here, producing cavernous sinus thrombosis with ophthalmoplegia, proptosis, and cranial neuropathies." },
  { term: "Pituitary gland", keys: ["Pituitary gland", "Pituitary"], def: "Endocrine gland seated in the sella turcica directly above the sphenoid sinus roof, accessed surgically via the transsphenoidal approach.", more: "the sphenoid sinus's direct relationship to the sella is what makes endoscopic transsphenoidal surgery the standard route to pituitary tumors, avoiding a craniotomy." },
  { term: "FESS (functional endoscopic sinus surgery)", keys: ["FESS (functional endoscopic sinus surgery)", "functional endoscopic sinus surgery", "FESS"], def: "Endoscopic reopening of natural drainage pathways.", more: "indicated for CRS refractory to an adequate trial of medical therapy (typically ≥ several weeks of intranasal steroids ± saline, and appropriate courses for the phenotype), and for polyps, mucoceles, or fungal disease." },
  { term: "Chronic rhinosinusitis (CRS)", keys: ["Chronic rhinosinusitis (CRS)", "Chronic rhinosinusitis", "CRS"], def: "≥12 weeks of ≥2 cardinal symptoms with objective confirmation.", more: "symptoms alone are insufficient beyond 12 weeks — diagnosis requires objective evidence of inflammation on endoscopy or CT." },
  { term: "CRSsNP / CRSwNP", keys: ["CRSsNP / CRSwNP"], def: "Without vs with nasal polyps.", more: "polyps are present in ~20% of CRS patients; CRSwNP is typically type-2/eosinophil-driven and more recurrent, steered toward steroids then biologics or FESS when refractory." },
  { term: "Nasal polyps", keys: ["Nasal polyps"], def: "Benign edematous type-2 mucosal outgrowths.", more: "FDA-approved biologics for CRSwNP include dupilumab, omalizumab, and mepolizumab, reserved for disease inadequately controlled by intranasal steroids ± surgery." },
  { term: "AERD (Samter's triad)", keys: ["AERD (Samter's triad)", "Samter's triad", "AERD"], def: "CRSwNP + asthma + NSAID/aspirin sensitivity.", more: "driven by COX-1 inhibition shunting arachidonic acid toward cysteinyl leukotrienes — the basis for both NSAID avoidance and supervised aspirin desensitization in refractory cases." },
  { term: "Allergic rhinitis", keys: ["Allergic rhinitis"], def: "IgE-mediated nasal inflammation with itch, sneezing, watery rhinorrhea, congestion.", more: "for persistent moderate-to-severe disease, regularly dosed intranasal corticosteroids are first-line, outperforming oral antihistamines for congestion." },
  { term: "ARIA classification", keys: ["ARIA classification"], def: "Grades by duration (intermittent vs persistent) and severity (mild vs moderate-severe).", more: "persistent = symptoms >4 days/week and >4 consecutive weeks; this axis, not the old seasonal/perennial split, drives step-up therapy." },
  { term: "Rhinitis medicamentosa", keys: ["Rhinitis medicamentosa"], def: "Rebound congestion from topical decongestant overuse.", more: "risk rises sharply beyond ~3–5 days of oxymetazoline; treat by stopping the spray and bridging with an intranasal steroid." },
  { term: "Vasomotor (non-allergic) rhinitis", keys: ["Vasomotor (non-allergic) rhinitis"], def: "Irritant/temperature-triggered congestion and rhinorrhea without itch/sneeze/conjunctivitis.", more: "allergy testing is negative; first-line is intranasal antihistamine or ipratropium rather than oral antihistamines, which are largely ineffective here." },
  { term: "Beta-2 transferrin", keys: ["Beta-2 transferrin"], def: "Protein nearly unique to CSF (and perilymph); confirmatory test for CSF rhinorrhea.", more: "a positive result mandates leak localization (high-resolution CT ± MR cisternography) and precludes reflexive nasal packing, which can drive an ascending meningitis." },
  { term: "Juvenile nasopharyngeal angiofibroma (JNA)", keys: ["Juvenile nasopharyngeal angiofibroma (JNA)", "Juvenile nasopharyngeal angiofibroma", "JNA"], def: "Benign but highly vascular nasopharyngeal tumor of adolescent males.", more: "clinic biopsy is contraindicated because of hemorrhage risk — diagnose by contrast imaging then angiography ± preoperative embolization before excision." },
  { term: "Inverted papilloma", keys: ["Inverted papilloma"], def: "Locally aggressive unilateral sinonasal tumor.", more: "carries a ~5–10% risk of harboring or progressing to squamous cell carcinoma, so it requires complete excision with margin control (often endoscopic medial maxillectomy), not simple polypectomy." },
  { term: "Esthesioneuroblastoma", keys: ["Esthesioneuroblastoma"], def: "Malignant olfactory-neuroepithelium tumor high in the olfactory groove.", more: "it straddles the cribriform plate, so staging (Kadish/Dulguerov) and treatment hinge on skull-base and intracranial extension — typically craniofacial/endoscopic resection plus radiation." },
  { term: "Hereditary hemorrhagic telangiectasia (HHT / Osler-Weber-Rendu)", keys: ["Hereditary hemorrhagic telangiectasia (HHT / Osler-Weber-Rendu)", "Hereditary hemorrhagic telangiectasia", "Osler-Weber-Rendu", "HHT"], def: "Autosomal-dominant vascular disorder with recurrent epistaxis, telangiectasias, visceral AVMs.", more: "diagnosed by the Curaçao criteria (epistaxis, telangiectasias, visceral AVMs, affected first-degree relative — 3 of 4 = definite); screen for pulmonary and cerebral AVMs given stroke/abscess risk." },
  { term: "Cervical nodal levels (I–VII)", keys: ["Cervical nodal levels (I–VII)", "Cervical nodal levels", "I–VII"], def: "Robbins map of neck node regions with defined boundaries and drainage.", more: "levels II–IV follow the internal jugular chain and are the first-echelon basins for most mucosal head-and-neck primaries, guiding selective dissection design." },
  { term: "Level VII", keys: ["Level VII"], def: "Superior mediastinal nodes below the sternal notch.", more: "chiefly relevant to thyroid and cervical-esophageal cancer staging, where paratracheal (level VI) and level VII spread predict recurrent laryngeal nerve proximity and mediastinal extension." },
  { term: "Parotid gland", keys: ["Parotid gland", "Parotid"], def: "Largest salivary gland, draining via Stensen's duct, split by the facial nerve.", more: "~85% of salivary tumors arise here and ~80% of parotid tumors are benign — documenting facial-nerve function before and after any parotid surgery is essential." },
  { term: "Stensen's duct", keys: ["Stensen's duct"], def: "Parotid duct over the masseter, opening opposite the upper second molar.", more: "a cheek laceration along the tragus-to-midphiltrum line risks duct and facial-nerve buccal branch injury together — probe and repair the duct over a stent." },
  { term: "Wharton's duct", keys: ["Wharton's duct"], def: "Submandibular duct opening at the sublingual caruncle.", more: "its uphill course against gravity plus thicker mucinous saliva explains why ~80–90% of salivary stones form here." },
  { term: "Sialolithiasis", keys: ["Sialolithiasis"], def: "Duct calculi causing painful, meal-related gland swelling.", more: "stimulated saliva backs up against the obstruction — the reason swelling peaks at mealtimes and settles between meals; most common in the submandibular gland via Wharton's duct." },
  { term: "Fine-needle aspiration (FNA)", keys: ["Fine-needle aspiration (FNA)", "Fine-needle aspiration", "FNA"], def: "First-line tissue sampling for a neck mass.", more: "strongly preferred over open excisional biopsy, which can seed tumor and compromise later neck dissection — image-guided FNA/core improves yield for cystic nodes." },
  { term: "p16 immunohistochemistry", keys: ["p16 immunohistochemistry", "p16"], def: "Surrogate marker for HPV-driven oropharyngeal SCC.", more: "positivity is scored when ≥70% of tumor cells show strong nuclear and cytoplasmic staining, and it triggers a distinct, more favorable AJCC staging system." },
  { term: "Epstein-Barr virus (EBV)", keys: ["Epstein-Barr virus (EBV)", "Epstein-Barr virus", "EBV"], def: "Herpesvirus linked to nasopharyngeal carcinoma and certain lymphomas.", more: "EBV-encoded RNA (EBER) in situ hybridization on a neck-node biopsy is the diagnostic clue that points back to an occult nasopharyngeal primary." },
  { term: "Panendoscopy", keys: ["Panendoscopy"], def: "Operative endoscopic survey of the upper aerodigestive tract (nasopharynx, oropharynx, larynx, hypopharynx, esophagus, ± bronchoscopy) under anesthesia.", more: "used to stage a known head & neck cancer, biopsy it, and screen for a synchronous second primary -- field cancerization means tobacco/alcohol-driven cancers cluster." },
  { term: "Oropharynx", keys: ["Oropharynx"], def: "The pharynx from the soft palate to the hyoid, including the tonsils, tongue base, and posterior pharyngeal wall.", more: "it is separated from the oral cavity by the plane through the hard-soft palate junction and circumvallate papillae -- the anatomic line that splits classically tobacco-driven oral cavity cancer from increasingly HPV-driven oropharyngeal cancer." },
  { term: "Oral cavity", keys: ["Oral cavity"], def: "The mouth from the lips to the hard-soft palate junction and circumvallate papillae, including the tongue's anterior two-thirds, floor of mouth, buccal mucosa, and gingiva.", more: "cancer here is classically tobacco- and alcohol-driven, presents early as a visible sore, and is staged and treated differently from the HPV-associated cancers just behind it in the oropharynx." },
  { term: "Carotid sheath", keys: ["Carotid sheath"], def: "Fascial tube enclosing the common/internal carotid artery, internal jugular vein, and vagus nerve together down the neck.", more: "it is the key surgical landmark for exposing the great vessels, and a deep neck infection tracking within it risks carotid blowout or internal jugular (Lemierre) thrombophlebitis." },
  { term: "HPV-associated oropharyngeal cancer", keys: ["HPV-associated oropharyngeal cancer"], def: "HPV-driven OPSCC in younger non-smokers, often a painless cystic node.", more: "a cystic neck node in an adult >40 must not be assumed to be a branchial cleft cyst — it is metastatic HPV+ SCC until proven otherwise." },
  { term: "Nasopharyngeal carcinoma (NPC)", keys: ["Nasopharyngeal carcinoma (NPC)", "Nasopharyngeal carcinoma", "NPC"], def: "EBV-associated cancer endemic to southern China/SE Asia.", more: "new unilateral serous otitis media in an adult is nasopharyngeal carcinoma until excluded by nasopharyngoscopy — it reflects Eustachian tube obstruction; the tumor is radiosensitive, treated primarily with radiation ± chemotherapy." },
  { term: "TI-RADS", keys: ["TI-RADS"], def: "ACR ultrasound risk stratification for thyroid nodules.", more: "points across five features set the FNA threshold — e.g., TR5 nodules are aspirated at ≥1 cm, TR4 at ≥1.5 cm, and TR3 at ≥2.5 cm." },
  { term: "Bethesda System", keys: ["Bethesda System"], def: "Six-tier thyroid FNA cytology framework.", more: "malignancy risk climbs from ~5–10% for category III (AUS) to ~25–40% for IV, ~50–75% for V, and ~97–99% for VI — each tier steering repeat FNA, molecular testing, lobectomy, or thyroidectomy." },
  { term: "Pleomorphic adenoma", keys: ["Pleomorphic adenoma"], def: "Most common benign salivary/parotid tumor.", more: "carries a small but real risk of malignant transformation (~1.5% early, rising to ~10% after ~15 years) — the reason it is excised with a cuff rather than enucleated or observed." },
  { term: "Warthin tumor", keys: ["Warthin tumor"], def: "Second most common benign parotid tumor in elderly male smokers.", more: "uniquely bilateral or multifocal in up to ~10% of cases and avidly takes up technetium-99m — often incidentally PET-avid, a benign pitfall on staging scans." },
  { term: "Mucoepidermoid carcinoma", keys: ["Mucoepidermoid carcinoma"], def: "Most common malignant salivary tumor.", more: "graded low-to-high on mucous-vs-epidermoid cell ratio and often driven by the MAML2 fusion; grade, more than stage, predicts behavior in early disease." },
  { term: "Adenoid cystic carcinoma", keys: ["Adenoid cystic carcinoma"], def: "Salivary malignancy favoring minor glands (classically palate).", more: "hallmarked by perineural invasion and late distant metastasis (often lung) even a decade out — cure is judged over long horizons, so \"no evidence of disease at 5 years\" does not equal cure." },
  { term: "Perineural invasion", keys: ["Perineural invasion", "Perineural spread"], def: "Tumor spread along nerve sheaths.", more: "it produces pain or numbness out of proportion to mass size and skip lesions along the nerve — a driver of local recurrence and an indication for adjuvant radiation." },
  { term: "Selective neck dissection", keys: ["Selective neck dissection"], def: "Removes only the highest-risk levels while preserving non-lymphatic structures.", more: "standard for the clinically node-negative (cN0) neck when the occult metastasis risk exceeds ~15–20%." },
  { term: "Modified radical neck dissection", keys: ["Modified radical neck dissection"], def: "Removes levels I–V, sparing at least one of SCM, IJV, or spinal accessory nerve.", more: "preserving the spinal accessory nerve is prioritized to avoid shoulder-drop morbidity while still clearing node-positive disease." },
  { term: "Radical neck dissection", keys: ["Radical neck dissection"], def: "Removes levels I–V plus SCM, IJV, and spinal accessory nerve.", more: "reserved for bulky nodal disease — bilateral IJV sacrifice risks fatal facial/cerebral venous congestion and is avoided in a single stage." },
  { term: "Virchow's node", keys: ["Virchow's node"], def: "Enlarged left supraclavicular node suggesting a sub-diaphragmatic primary.", more: "it sits at the thoracic duct's junction with the left subclavian vein, so metastatic seeding here prompts imaging of the abdomen/pelvis, not just the neck." },
  { term: "Leukoplakia", keys: ["Leukoplakia"], def: "White mucosal patch that cannot be wiped off or otherwise explained.", more: "overall malignant transformation is roughly ~1–5%, higher for non-homogeneous or floor-of-mouth/ventral-tongue lesions — biopsy rather than observe." },
  { term: "Erythroplakia", keys: ["Erythroplakia"], def: "Red mucosal patch, less common than leukoplakia.", more: "far higher risk — the majority already show severe dysplasia, carcinoma in situ, or invasive SCC on biopsy, so it always warrants biopsy." },
  { term: "TNM staging", keys: ["TNM staging"], def: "Classifies by primary Tumor, regional Node, distant Metastasis.", more: "HPV+ oropharyngeal cancer uses a separate staging table — applying the HPV-negative criteria will markedly overstage these favorable tumors." },
  { term: "Plummer-Vinson syndrome", keys: ["Plummer-Vinson syndrome"], def: "Iron-deficiency anemia + esophageal web + dysphagia.", more: "predisposes specifically to postcricoid/hypopharyngeal carcinoma — correcting the anemia relieves symptoms but does not substitute for excluding malignancy." },
  { term: "Osteoradionecrosis", keys: ["Osteoradionecrosis"], def: "Non-healing exposed bone in a previously irradiated mandible.", more: "risk rises sharply above ~60 Gy, so high-risk teeth are extracted before radiotherapy and post-radiation extractions from the irradiated field are avoided." },
  { term: "Free flap", keys: ["Free flap"], def: "Distant tissue with its own pedicle, microvascularly reanastomosed at the defect.", more: "modern success rates exceed ~95%; flap monitoring is most critical in the first 48–72 hours when the majority of salvageable thromboses occur." },
  { term: "Field cancerization", keys: ["Field cancerization"], def: "Diffuse carcinogen exposure priming the whole aerodigestive mucosa.", more: "it drives a second-primary risk of roughly 3–4% per year, the rationale for years-long post-treatment surveillance and continued tobacco/alcohol cessation." },
  { term: "Larynx (subsites)", keys: ["Larynx (subsites)", "subsites", "Larynx"], def: "The voice box, divided into three surgically and oncologically distinct subsites: the supraglottis (epiglottis, false cords, aryepiglottic folds), the glottis (true vocal cords), and the subglottis (down to the cricoid). The glottis has sparse lymphatics, so glottic cancers present early with hoarseness and metastasize late; the supraglottis is lymphatic-rich and presents with early nodal spread.", more: null },
  { term: "True vocal cord (vocal fold)", keys: ["True vocal cord (vocal fold)", "True vocal cord", "vocal fold"], def: "The vibrating shelf of the glottis, built as a layered structure — epithelium, the pliable superficial lamina propria (Reinke's space), and the vocalis muscle. Vibration occurs in a mucosal wave over Reinke's space; any lesion that stiffens this layer (scar, sulcus) causes hoarseness that surgery cannot always restore.", more: null },
  { term: "Recurrent laryngeal nerve (RLN)", keys: ["Recurrent laryngeal nerve (RLN)", "Recurrent laryngeal nerve", "RLN"], def: "The branch of the vagus supplying all intrinsic laryngeal muscles except the cricothyroid. Its long left course loops under the aortic arch, making it vulnerable to thyroid surgery, mediastinal disease, and aortic pathology; injury produces a paramedian cord and a breathy voice.", more: null },
  { term: "Superior laryngeal nerve (external branch)", keys: ["Superior laryngeal nerve (external branch)", "Superior laryngeal nerve", "external branch"], def: "Motor to the cricothyroid muscle, which tenses the cord for pitch. Injury (classically in thyroidectomy near the superior pole vessels) causes loss of high pitch and vocal fatigue — subtle, and easily missed in a non-singer.", more: null },
  { term: "Vocal cord paralysis (unilateral)", keys: ["Vocal cord paralysis (unilateral)"], def: "Immobile cord from RLN injury; the affected cord sits in a paramedian position and the voice is breathy with weak cough. Up to a third are idiopathic, but a new unilateral paralysis without a surgical cause mandates imaging from skull base to aortopulmonary window to exclude tumor.", more: null },
  { term: "Vocal cord paralysis (bilateral)", keys: ["Vocal cord paralysis (bilateral)"], def: "Both cords immobile, typically in a near-midline position after thyroid surgery; the danger is airway obstruction and stridor rather than voice change, and it may require tracheostomy or cordotomy.", more: null },
  { term: "Vocal fold nodules", keys: ["Vocal fold nodules"], def: "Bilateral, symmetric \"singer's nodules\" at the mid-membranous cord (the point of maximal vibratory impact), caused by phonotrauma. First-line treatment is voice therapy, not surgery — a classic pitfall is operating on what behavior can resolve.", more: null },
  { term: "Vocal fold polyp", keys: ["Vocal fold polyp"], def: "Usually a unilateral, often hemorrhagic lesion from a single phonotraumatic event; unlike nodules, polyps more often require microsurgical excision after a trial of voice rest and therapy.", more: null },
  { term: "Reinke's edema (polypoid corditis)", keys: ["Reinke's edema (polypoid corditis)", "polypoid corditis", "Reinke's edema"], def: "Diffuse, bilateral fluid accumulation in the superficial lamina propria, almost exclusively in smokers, producing a low, gravelly voice. Smoking cessation is mandatory; a low-pitched voice in a woman is the classic clue.", more: null },
  { term: "Laryngopharyngeal reflux (LPR)", keys: ["Laryngopharyngeal reflux (LPR)", "Laryngopharyngeal reflux", "LPR"], def: "Retrograde gastric content reaching the larynx/pharynx, producing throat clearing, globus, cough, and hoarseness. Laryngoscopic signs (posterior commissure hypertrophy, arytenoid edema) are nonspecific — up to ~86% of asymptomatic adults show them — so symptoms plus signs do not equal disease; objective reflux testing (pH-impedance) is required before committing to long-term acid suppression when symptoms are isolated or refractory.", more: null },
  { term: "Muscle tension dysphonia", keys: ["Muscle tension dysphonia"], def: "Effortful, strained voice from maladaptive laryngeal muscle recruitment with structurally normal cords; a primary functional disorder or secondary to reflux/lesion. Diagnosed by ruling out structural disease and treated with voice therapy.", more: null },
  { term: "Laryngoscopy with stroboscopy", keys: ["Laryngoscopy with stroboscopy"], def: "Adds a strobe light synchronized near the vocal frequency to \"slow down\" and reveal the mucosal wave; the key test for detecting subtle stiffness (scar, early cancer, sulcus) invisible on standard exam.", more: null },
  { term: "FEES", keys: ["FEES"], def: "Flexible Endoscopic Evaluation of Swallowing: a transnasal scope watches the pharynx and larynx directly while the patient swallows trial foods/liquids.", more: "unlike a modified barium swallow it needs no radiation and gives a direct view of residue/penetration/aspiration, but it can't see the brief moment of swallow itself (\"white-out\")." },
  { term: "Botulinum toxin (Botox)", keys: ["Botulinum toxin (Botox)", "Botulinum toxin", "Botox"], def: "A neurotoxin that causes temporary, reversible chemodenervation by blocking acetylcholine release at the neuromuscular junction.", more: "in laryngology it's injected into the thyroarytenoid/vocalis for spasmodic dysphonia and into synkinetic facial muscles after facial nerve injury; effects wear off over months, requiring repeat injections." },
  { term: "Spasmodic dysphonia", keys: ["Spasmodic dysphonia"], def: "A focal laryngeal dystonia causing task-specific voice breaks (strained-strangled in the adductor type); treated with targeted botulinum toxin injection into the thyroarytenoid, repeated roughly every 3 months.", more: null },
  { term: "Laryngeal papillomatosis (RRP)", keys: ["Laryngeal papillomatosis (RRP)", "Laryngeal papillomatosis", "RRP"], def: "Recurrent respiratory papillomas from HPV 6 and 11, seeded during vaginal birth in the juvenile form; wart-like airway lesions that recur after debulking, with a small risk of malignant transformation (especially HPV 11).", more: null },
  { term: "Laryngeal squamous cell carcinoma", keys: ["Laryngeal squamous cell carcinoma"], def: "The dominant laryngeal malignancy, tobacco- and alcohol-driven; glottic tumors declare themselves early with hoarseness (>2–3 weeks of hoarseness in a smoker demands laryngoscopy), whereas supraglottic tumors present later with a neck node or dysphagia.", more: null },
  { term: "Tracheostomy", keys: ["Tracheostomy"], def: "A surgical airway placed between the second and fourth tracheal rings; the feared early complication is tube displacement before a tract has matured (~5–7 days), when blind reinsertion can create a false passage.", more: null },
  { term: "Tracheoinnominate fistula", keys: ["Tracheoinnominate fistula"], def: "A rare, catastrophic erosion of the tracheostomy tube into the innominate artery, classically 3 days to 6 weeks post-op. A \"sentinel bleed\" precedes exsanguination; initial control is overinflating the cuff or applying anterior digital pressure through the stoma.", more: null },
  { term: "Adenoids", keys: ["Adenoids"], def: "Nasopharyngeal lymphoid tissue that peaks in size around ages 3–7 and normally regresses by adolescence; hypertrophy causes mouth breathing, hyponasal speech, and Eustachian tube obstruction with recurrent otitis media.", more: null },
  { term: "Adenoidectomy", keys: ["Adenoidectomy"], def: "Removal of the adenoid pad, a separate operation from tonsillectomy with different indications (nasal obstruction, chronic/recurrent otitis media, chronic adenoiditis). It is often combined with tympanostomy tubes for recurrent OME.", more: null },
  { term: "Tonsillectomy — Paradise criteria", keys: ["Paradise criteria"], def: "The frequency threshold defining \"severe recurrent throat infection\" that justifies tonsillectomy: ≥7 documented episodes in 1 year, ≥5/year for 2 years, or ≥3/year for 3 years, each episode with a qualifying feature (temp >38.3°C, cervical adenopathy, exudate, or positive GAS). Below this, watchful waiting is favored unless modifying factors (e.g., PFAPA, multiple antibiotic allergies) are present.", more: null },
  { term: "Adenotonsillectomy for OSA", keys: ["Adenotonsillectomy for OSA"], def: "The first-line surgical treatment for pediatric obstructive sleep-disordered breathing; the CHAT trial showed benefit over watchful waiting for polysomnographic, behavioral, and quality-of-life outcomes. Inpatient observation is advised for children under age 3 or with severe OSA (AHI >10 or oxygen nadir <80%).", more: null },
  { term: "Tympanostomy tubes", keys: ["Tympanostomy tubes"], def: "Ventilation tubes placed for recurrent AOM or persistent OME; the standard threshold is bilateral OME persisting ≥3 months with hearing loss, or recurrent AOM (≥3 in 6 months / ≥4 in 12 months) with effusion.", more: null },
  { term: "Laryngomalacia", keys: ["Laryngomalacia"], def: "The most common cause of infant stridor (up to ~45–78% of cases), from dynamic inspiratory collapse of soft supraglottic structures; produces intermittent inspiratory stridor worse with feeding, crying, and supine position, typically self-resolving by 12–24 months. Diagnosis is by flexible laryngoscopy showing the dynamic collapse.", more: null },
  { term: "Supraglottoplasty", keys: ["Supraglottoplasty"], def: "The surgical treatment for the ~10% of laryngomalacia cases that are severe (failure to thrive, aspiration, significant obstruction); it divides tight aryepiglottic folds and trims redundant supraglottic tissue, resolving stridor in most.", more: null },
  { term: "Subglottic stenosis", keys: ["Subglottic stenosis"], def: "Narrowing at the cricoid, the only complete cartilage ring and the narrowest point of the pediatric airway; most acquired cases follow prolonged intubation. It produces biphasic stridor, and severity is graded by the Myer-Cotton system (I–IV by percent luminal obstruction).", more: null },
  { term: "Choanal atresia", keys: ["Choanal atresia"], def: "Bony or membranous blockage of the posterior nasal aperture. Bilateral atresia presents at birth with cyclical cyanosis relieved by crying (neonates are obligate nasal breathers); the bedside clue is inability to pass a catheter through the nose. It is associated with CHARGE syndrome.", more: null },
  { term: "Laryngeal cleft", keys: ["Laryngeal cleft"], def: "A posterior midline defect between larynx and esophagus allowing aspiration; presents with feeding-associated coughing/choking and recurrent pneumonia, and is graded by the Benjamin-Inglis classification by depth of the cleft.", more: null },
  { term: "Branchial cleft anomaly", keys: ["Branchial cleft anomaly"], def: "Congenital lateral neck cyst/sinus from incomplete branchial apparatus involution; the second-cleft cyst (the most common) sits along the anterior border of the sternocleidomastoid. A \"branchial cyst\" first appearing after age 40 must be treated as a cystic metastasis until proven otherwise.", more: null },
  { term: "Thyroglossal duct cyst", keys: ["Thyroglossal duct cyst"], def: "The most common congenital midline neck cyst, arising along the thyroid's descent from the foramen cecum; it classically elevates with tongue protrusion and swallowing. The Sistrunk procedure (excising the cyst with the mid-portion of the hyoid) is required to prevent recurrence.", more: null },
  { term: "Cystic hygroma (lymphatic malformation)", keys: ["Cystic hygroma (lymphatic malformation)", "lymphatic malformation", "Cystic hygroma"], def: "A soft, compressible, transilluminating neck mass from maldeveloped lymphatics, usually presenting by age 2 in the posterior triangle; can enlarge abruptly with infection or intralesional bleeding.", more: null },
  { term: "Croup (laryngotracheobronchitis)", keys: ["Croup (laryngotracheobronchitis)", "laryngotracheobronchitis", "Croup"], def: "Viral subglottic inflammation (parainfluenza) with barky cough and inspiratory stridor; the \"steeple sign\" of subglottic narrowing may appear on AP neck film. Treated with dexamethasone, and nebulized epinephrine for moderate-to-severe cases.", more: null },
  { term: "Obstructive sleep apnea (OSA)", keys: ["Obstructive sleep apnea (OSA)", "Obstructive sleep apnea", "OSA"], def: "Repetitive pharyngeal collapse during sleep causing apneas/hypopneas, arousals, and desaturations; diagnosed by polysomnography and graded by the apnea-hypopnea index (AHI 5–15 mild, 15–30 moderate, >30 severe).", more: null },
  { term: "Apnea-hypopnea index (AHI)", keys: ["Apnea-hypopnea index (AHI)", "Apnea-hypopnea index", "AHI"], def: "The number of apneas plus hypopneas per hour of sleep, the core severity metric of OSA; an AHI ≥5 with symptoms, or ≥15 regardless of symptoms, meets diagnostic criteria.", more: null },
  { term: "STOP-BANG", keys: ["STOP-BANG"], def: "An 8-item screening tool (Snoring, Tiredness, Observed apnea, Pressure, BMI, Age, Neck, Gender); a score ≥3 flags elevated OSA risk and ≥5 suggests high risk of moderate-to-severe disease.", more: null },
  { term: "Continuous positive airway pressure (CPAP)", keys: ["Continuous positive airway pressure (CPAP)", "Continuous positive airway pressure", "CPAP"], def: "The most efficacious OSA treatment, pneumatically splinting the airway open; its real-world limitation is adherence, and the surgical/alternative pathways exist chiefly for the substantial fraction of patients who cannot tolerate it.", more: null },
  { term: "Uvulopalatopharyngoplasty (UPPP)", keys: ["Uvulopalatopharyngoplasty (UPPP)", "Uvulopalatopharyngoplasty", "UPPP"], def: "Resection/reconfiguration of the uvula, soft palate, and tonsillar pillars to enlarge the retropalatal airway; effective for palatal-level obstruction but with variable success, so anatomic phenotyping guides selection.", more: null },
  { term: "Hypoglossal nerve stimulation", keys: ["Hypoglossal nerve stimulation"], def: "An implanted device that protrudes the tongue during inspiration via CN XII stimulation; indicated for moderate-to-severe OSA in patients intolerant of CPAP, with a BMI ≤32 kg/m² and without complete concentric palatal collapse on drug-induced sleep endoscopy.", more: null },
  { term: "Maxillomandibular advancement (MMA)", keys: ["Maxillomandibular advancement (MMA)", "Maxillomandibular advancement", "MMA"], def: "Skeletal surgery advancing both jaws to enlarge the entire velo-oro-hypopharyngeal airway; the most effective soft-tissue-sparing surgical option, more durable than UPPP for appropriate candidates.", more: null },
  { term: "Drug-induced sleep endoscopy (DISE)", keys: ["Drug-induced sleep endoscopy (DISE)", "Drug-induced sleep endoscopy", "DISE"], def: "Flexible endoscopy during pharmacologically induced sleep to identify the level(s) and pattern of collapse (VOTE: velum, oropharynx, tongue base, epiglottis); complete concentric palatal collapse is a contraindication to hypoglossal nerve stimulation.", more: null },
  { term: "Facial nerve (CN VII) segments", keys: ["Facial nerve (CN VII) segments", "Facial nerve"], def: "The nerve's course runs intracranial → internal auditory canal → labyrinthine (narrowest segment, the site of entrapment in Bell's palsy) → tympanic → mastoid, exiting at the stylomastoid foramen. The labyrinthine segment's tight bony canal explains why edema there causes ischemic paralysis.", more: null },
  { term: "Bell's palsy", keys: ["Bell's palsy"], def: "Acute idiopathic (largely HSV-linked) unilateral lower-motor-neuron facial paralysis of exclusion, involving the forehead. Early oral corticosteroids improve recovery; surgical decompression evidence remains insufficient to recommend routinely. Forehead sparing instead points to a central (upper-motor-neuron) lesion.", more: null },
  { term: "Ramsay Hunt syndrome (herpes zoster oticus)", keys: ["Ramsay Hunt syndrome (herpes zoster oticus)", "Ramsay Hunt syndrome", "herpes zoster oticus"], def: "VZV reactivation in the geniculate ganglion causing facial palsy plus a painful vesicular rash in the ear canal/auricle, often with hearing loss and vertigo; it has a worse prognosis than Bell's palsy, so antivirals plus steroids are started promptly.", more: null },
  { term: "Synkinesis", keys: ["Synkinesis"], def: "Aberrant facial nerve regeneration causing involuntary co-contraction (e.g., eye closure with smiling); a late sequela of facial palsy managed with targeted botulinum toxin and neuromuscular retraining rather than further surgery.", more: null },
  { term: "Nasal septal hematoma", keys: ["Nasal septal hematoma", "Septal hematoma"], def: "Blood collection between septal cartilage and perichondrium after trauma, stripping the cartilage of its blood supply; if not drained urgently it causes avascular necrosis and a saddle-nose deformity. The exam clue is a boggy, fluctuant septal swelling obstructing both sides.", more: null },
  { term: "Auricular hematoma", keys: ["Auricular hematoma"], def: "Subperichondrial blood in the pinna (\"wrestler's ear\") that, if not evacuated with a pressure dressing, organizes into the fibrocartilaginous \"cauliflower ear\"; time-sensitive because the cartilage depends on the perichondrium for perfusion.", more: null },
  { term: "Nasal bone fracture", keys: ["Nasal bone fracture"], def: "The most common facial fracture; assessment is best repeated at 3–5 days once swelling settles, and closed reduction is ideally performed within ~2 weeks before the fracture sets. Always exclude a septal hematoma first.", more: null },
  { term: "Orbital blowout fracture", keys: ["Orbital blowout fracture"], def: "Fracture of the thin orbital floor (or medial wall) from a blunt globe injury; entrapment of the inferior rectus causes vertical diplopia, and a \"trapdoor\" fracture in a child with the oculocardiac reflex (bradycardia, nausea) is a surgical emergency.", more: null },
  { term: "Le Fort fractures", keys: ["Le Fort fractures"], def: "A classification of midface fractures by the plane of the fracture (I transverse maxilla, II pyramidal, III craniofacial disjunction), all crossing the pterygoid plates; they signal high-energy trauma and airway risk from a mobile, retro-displaced midface.", more: null },
  { term: "Temporal bone fracture", keys: ["Temporal bone fracture"], def: "Skull-base fracture classified as longitudinal (more common, along the petrous axis, causing conductive loss and ossicular disruption) or transverse (crossing the axis, higher risk of sensorineural loss and facial paralysis). CSF otorrhea and Battle's sign are supporting signs.", more: null },
  { term: "Mandible fracture", keys: ["Mandible fracture"], def: "Frequently occurs in pairs because of the ring-like mandible; malocclusion is the most sensitive clinical sign, and condylar/angle regions are common sites. Fractures through a tooth-bearing segment are effectively open and warrant antibiotics.", more: null },
  { term: "Septorhinoplasty", keys: ["Septorhinoplasty"], def: "Combined functional and aesthetic reshaping of the nasal septum and framework; over-resection of dorsal or caudal septal cartilage risks late saddle-nose or tip ptosis, so preserving an adequate structural strut is the key principle.", more: null },
  { term: "Local/regional flap", keys: ["Local/regional flap"], def: "Reconstruction using adjacent tissue moved on its own blood supply (e.g., paramedian forehead flap for nasal defects); chosen when tissue quality and defect size allow closure without the complexity of free-tissue transfer.", more: null },
  { term: "Open middle ear", keys: ["Open middle ear"], def: "The state in which a perforated tympanic membrane or a patent tympanostomy tube exposes the middle ear (and, through the round/oval window, the inner ear) to anything instilled in the ear canal.", more: "A drop reaches the inner ear only via the round window membrane, which is why an aminoglycoside can be cochleotoxic once the drum is not intact but is safe on an intact drum." },
  { term: "Ototoxicity", keys: ["Ototoxicity"], def: "Drug-induced injury to the cochlea or vestibular system causing hearing loss, tinnitus, or imbalance.", more: "Topical aminoglycosides, alcohol, and acidifying drops are the classic offenders through an open middle ear; assume a tube is patent for roughly 12 months after placement unless drum closure is documented (teaching convention — confirm locally)." },
  { term: "Non-ototoxic fluoroquinolone otic drop", keys: ["Non-ototoxic fluoroquinolone otic drop"], def: "Topical quinolone (ofloxacin, or ciprofloxacin ± dexamethasone) safe for use through a perforation or tube and first-line for tube otorrhea and chronic suppurative otitis media.", more: "For tube otorrhea/CSOM, topical antibiotics are preferred over oral because local drug concentration is far higher than achievable systemically." },
  { term: "Idiopathic sudden sensorineural hearing loss (ISSNHL)", keys: ["Idiopathic sudden sensorineural hearing loss (ISSNHL)", "Idiopathic sudden sensorineural hearing loss", "ISSNHL", "Sudden SNHL"], def: "Otologic emergency defined as ≥30 dB sensorineural loss across ≥3 contiguous frequencies developing within 72 hours.", more: "Steroids are most effective when started within about 2 weeks of onset; treat within 7 days when possible, and obtain an audiogram to confirm plus MRI to exclude retrocochlear pathology." },
  { term: "Steroid dose equivalence", keys: ["Steroid dose equivalence"], def: "Conversion used to avoid underdosing when switching corticosteroids: prednisone 60 mg ≈ methylprednisolone 48 mg ≈ dexamethasone 10 mg.", more: "Cautions include hyperglycemia, insomnia, mood change, and GI upset; use care in diabetes, uncontrolled hypertension, and peptic ulcer disease." },
  { term: "Intratympanic steroid", keys: ["Intratympanic steroid"], def: "Corticosteroid injected across the tympanic membrane into the middle ear, used as salvage after failed oral steroids or first-line when systemic steroids are risky (e.g., poorly controlled diabetes).", more: "Combined oral + intratympanic therapy is favored for severe/profound loss." },
  { term: "Peritonsillar abscess (quinsy)", keys: ["Peritonsillar abscess (quinsy)", "Peritonsillar abscess", "quinsy"], def: "Collection of pus between the tonsillar capsule and the superior constrictor muscle, presenting with trismus, \"hot potato\" voice, and uvular deviation.", more: "US incidence ~30 per 100,000/year; managed by needle aspiration or I&D plus antibiotics." },
  { term: "Deep neck space infection (DNSI)", keys: ["Deep neck space infection (DNSI)", "Deep neck space infection", "DNSI"], def: "Infection tracking along interconnected cervical fascial planes (parapharyngeal, retropharyngeal, submandibular, danger space) toward the airway, great vessels, and mediastinum.", more: "Surgical drainage is typically indicated for a discrete collection (often quoted as >2–2.5 cm), airway compromise, or failure of medical therapy." },
  { term: "Polymicrobial infection", keys: ["Polymicrobial infection"], def: "Infection caused by multiple organisms simultaneously; head and neck DNSIs mix aerobic gram-positives (*S. pyogenes*, *S. anginosus* group, *S. aureus*) with oral anaerobes (*Fusobacterium*, *Prevotella*).", more: "Anaerobes predominate in odontogenic sources, which is why empiric regimens must cover \"above-the-diaphragm\" anaerobes." },
  { term: "Ampicillin-sulbactam", keys: ["Ampicillin-sulbactam"], def: "First-line empiric IV agent for PTA/DNSI; the sulbactam beta-lactamase inhibitor restores coverage of oral anaerobes and many staphylococci.", more: "Adding metronidazole is redundant here because anaerobic coverage is already built in; reserve metronidazole for backbones that lack it (e.g., a cephalosporin)." },
  { term: "Clindamycin", keys: ["Clindamycin"], def: "Lincosamide covering streptococci, many staphylococci, and above-the-diaphragm anaerobes; used for penicillin-allergic patients and odontogenic infection.", more: "Do NOT rely on it as dependable MRSA coverage — community MRSA susceptibility is variable and inducible resistance requires D-test confirmation." },
  { term: "Metronidazole", keys: ["Metronidazole"], def: "Nitroimidazole with potent anaerobic (and antiprotozoal) activity but no aerobic gram-positive coverage.", more: "Add it only when the regimen backbone lacks anaerobic activity, e.g., ceftriaxone or cefuroxime; not needed with ampicillin-sulbactam." },
  { term: "Ciprofloxacin", keys: ["Ciprofloxacin"], def: "Fluoroquinolone with the best antipseudomonal activity but poor streptococcal coverage.", more: "A poor choice for strep-driven head and neck infection and never appropriate as MRSA monotherapy." },
  { term: "Lemierre syndrome", keys: ["Lemierre syndrome"], def: "Septic thrombophlebitis of the internal jugular vein, classically caused by *Fusobacterium necrophorum* after oropharyngeal infection, with septic pulmonary emboli.", more: "Oropharyngeal infection invades the parapharyngeal space and seeds the IJV, producing metastatic abscesses." },
  { term: "Invasive fungal head & neck disease", keys: ["Invasive fungal head & neck disease"], def: "Angioinvasive mould infection (e.g., *Aspergillus*, Mucorales) in immunocompromised or hyperglycemic hosts requiring antifungals plus surgical debridement.", more: "Angioinvasion causes vascular thrombosis and tissue necrosis (black eschar), so antifungal drug penetration into dead tissue is limited and surgery is essential." },
  { term: "Voriconazole", keys: ["Voriconazole"], def: "First-line triazole for invasive aspergillosis (isavuconazole is co–first-line).", more: "Has NO activity against Mucorales — a classic exam \"gotcha,\" since voriconazole prophylaxis is associated with breakthrough mucormycosis." },
  { term: "Liposomal amphotericin B", keys: ["Liposomal amphotericin B"], def: "Polyene, first-line for invasive mucormycosis; the liposomal formulation reduces nephrotoxicity versus conventional amphotericin.", more: "Binds fungal membrane ergosterol to form pores; must be paired with urgent surgical debridement and reversal of the host derangement (e.g., DKA)." },
  { term: "Isavuconazole", keys: ["Isavuconazole"], def: "Newer triazole, co–first-line with voriconazole for invasive aspergillosis and an accepted alternative for mucormycosis, with fewer drug interactions and less hepatotoxicity.", more: "Chosen when interaction burden or hepatic tolerance favors it over voriconazole." },
  { term: "Clostridioides difficile infection (CDI)", keys: ["Clostridioides difficile infection (CDI)", "Clostridioides difficile infection", "CDI"], def: "Antibiotic-associated colitis presenting as watery diarrhea with leukocytosis (which may precede diarrhea); prior antibiotic exposure is the dominant risk factor.", more: "Highest-risk classes are clindamycin, fluoroquinolones, cephalosporins, and carbapenems; lower risk with macrolides, penicillins, and sulfonamides." },
  { term: "Airway-first principle", keys: ["Airway-first principle"], def: "The rule that assessing and protecting the airway precedes forming any differential in an ENT emergency.", more: "Signs of impending obstruction — stridor, drooling/inability to handle secretions, tripod positioning, agitation progressing to lethargy, voice change — override the diagnostic work-up." },
  { term: "Tripod position", keys: ["Tripod position"], def: "Patient sitting upright, leaning forward on the arms with the neck extended and chin thrust forward to maximize airway patency.", more: "In suspected epiglottitis it signals a near-critical airway — keep the patient calm and do not force a supine position or throat exam." },
  { term: "\"When not to examine the throat\"", keys: [], def: "Rule that a tongue depressor or oropharyngeal exam is deferred in suspected epiglottitis (especially a drooling, tripoding child) until a controlled setting with airway backup is available.", more: "Manipulation can precipitate complete obstruction; definitive visualization is flexible laryngoscopy with ENT/anesthesia present." },
  { term: "Ludwig's angina", keys: ["Ludwig's angina"], def: "Rapidly spreading, usually odontogenic bilateral cellulitis of the submandibular, sublingual, and submental spaces that elevates and posteriorly displaces the tongue.", more: "It is a diffuse \"woody\" cellulitis, not a drainable pocket, so it can obstruct the airway before fluctuance develops — default to early awake fiberoptic intubation with surgical airway on standby." },
  { term: "Awake fiberoptic intubation", keys: ["Awake fiberoptic intubation"], def: "Securing the airway in a spontaneously breathing, minimally sedated patient using a flexible scope, preferred when distorted anatomy makes direct laryngoscopy and bag-mask ventilation unreliable.", more: "Preferred in Ludwig's angina and threatened deep-neck airways because sedation-induced apnea in a \"can't intubate, can't ventilate\" scenario is catastrophic." },
  { term: "Orbital (postseptal) cellulitis", keys: ["Orbital (postseptal) cellulitis", "Postseptal cellulitis"], def: "Infection posterior to the orbital septum, usually a complication of sinusitis, presenting with proptosis, painful/restricted eye movement, and vision change.", more: "Proptosis, ophthalmoplegia, decreasing vision, or an RAPD distinguish it from preseptal cellulitis and prompt urgent CT plus consideration of surgical drainage." },
  { term: "Preseptal (periorbital) cellulitis", keys: ["Preseptal (periorbital) cellulitis", "Periorbital cellulitis"], def: "Infection anterior to the orbital septum causing eyelid swelling/erythema but sparing eye movement and vision.", more: "Painful or restricted eye movement means the process is no longer preseptal — reclassify and image." },
  { term: "Acute invasive fungal sinusitis (mucormycosis)", keys: ["Acute invasive fungal sinusitis (mucormycosis)", "Acute invasive fungal sinusitis", "mucormycosis"], def: "Angioinvasive mould infection of the sinuses in diabetic (especially DKA) or immunocompromised hosts, with black necrotic eschar and facial pain/numbness.", more: "A same-hour surgical emergency — emergent biopsy/frozen section and debridement plus liposomal amphotericin B and correction of the metabolic derangement; do not wait for formal imaging or cultures." },
  { term: "Orbital compartment syndrome", keys: ["Orbital compartment syndrome"], def: "Rise in intraorbital pressure (usually from retrobulbar hemorrhage) compressing the optic nerve and its blood supply within the closed bony orbit.", more: "Irreversible vision loss can occur within roughly 60–120 minutes of significant ischemia, so treatment precedes imaging (teaching convention — confirm locally)." },
  { term: "Lateral canthotomy and inferior cantholysis", keys: ["Lateral canthotomy and inferior cantholysis"], def: "Bedside release of the lateral canthal tendon (and its inferior crus) to decompress the orbit in orbital compartment syndrome.", more: "Perform immediately when vision is acutely threatened and do not wait for CT; IOP-lowering agents (acetazolamide, mannitol) are adjuncts, not substitutes." },
  { term: "Relative afferent pupillary defect (RAPD)", keys: ["Relative afferent pupillary defect (RAPD)", "Relative afferent pupillary defect", "RAPD"], def: "Asymmetric pupillary light response indicating optic nerve or severe retinal dysfunction on the affected side.", more: "On the swinging-flashlight test the affected pupil paradoxically dilates when light swings to it, signaling that the optic nerve is functionally compromised and vision is under real threat." },
  { term: "SSNHL treatment window", keys: ["SSNHL treatment window"], def: "The time-sensitive period during which corticosteroids can improve recovery in sudden sensorineural hearing loss; earlier is better, ideally within about 2 weeks.", more: "Defined as ≥30 dB loss across ≥3 contiguous frequencies within 72 hours; confirm with an urgent audiogram before attributing symptoms to cerumen or effusion." },
  { term: "Post-thyroidectomy hematoma", keys: ["Post-thyroidectomy hematoma"], def: "Expanding neck hematoma after thyroid/neck surgery compressing the airway.", more: "The immediate action is to open the wound at the bedside (release skin and strap-muscle closure) to evacuate the clot BEFORE imaging or OR transport; definitive hemostasis follows in the OR." },
  { term: "Button battery impaction", keys: ["Button battery impaction", "Button battery"], def: "Disc battery lodged in the ear, nose, or (most dangerously) esophagus, causing hydrolysis-driven liquefactive necrosis within hours.", more: "An esophageal battery should be removed emergently, ideally within about 2 hours; honey (pre-hospital) and sucralfate (in-hospital) can mitigate injury while awaiting removal." },
  { term: "Liquefactive necrosis", keys: ["Liquefactive necrosis"], def: "Tissue destruction in which cells are digested into a liquid mass, characteristic of button-battery and alkali injury.", more: "At the battery's negative pole, current generates hydroxide ions, raising local pH and dissolving tissue — the reason removal is measured in hours, not days." },
  { term: "Caustic ingestion", keys: ["Caustic ingestion"], def: "Swallowing of a corrosive alkali or acid causing aerodigestive injury; do not induce vomiting, neutralize, or give charcoal.", more: "Absence of visible oral burns does NOT exclude significant esophageal injury, so a normal mouth cannot clear the esophagus." },
  { term: "Alkali vs. acid injury", keys: ["Alkali vs. acid injury"], def: "Alkali (e.g., drain cleaner) causes deeply penetrating liquefactive necrosis of the esophagus; acid causes coagulative necrosis forming a limiting surface eschar and tends to injure the stomach.", more: "Alkali saponifies lipids and penetrates the wall, whereas the acid eschar can partially self-limit depth." },
  { term: "Endoscopic injury grading (caustic)", keys: ["Endoscopic injury grading (caustic)", "Endoscopic injury grading", "caustic"], def: "Grading of caustic injury from I (mucosal edema/erythema) through IIa/IIb (superficial vs. deep/circumferential ulceration) to III (transmural necrosis).", more: "Performed within about 12–24 hours once stable; higher grades markedly raise the risk of later stricture, and grade III risks perforation/mediastinitis (teaching convention for timing — confirm locally)." },
  { term: "CSF rhinorrhea", keys: ["CSF rhinorrhea"], def: "Leakage of cerebrospinal fluid from a skull-base defect, suggested by a \"halo/ring\" sign on gauze and glucose-positive fluid.", more: "Avoid nasal packing near a suspected skull-base defect because of the meningitis risk; most traumatic leaks are first managed with head elevation and observation." },
  { term: "Angioedema", keys: ["Angioedema"], def: "Localized, non-pitting deep dermal/submucosal swelling of the lips, tongue, or airway; the key triage question is whether it is histamine- or bradykinin-mediated.", more: "Swelling without urticaria or itch points away from a histaminergic cause and toward a bradykinin mechanism that will not respond to the anaphylaxis triad." },
  { term: "Histamine (mast-cell)–mediated angioedema", keys: ["Histamine (mast-cell)–mediated angioedema", "Mast-cell-mediated angioedema"], def: "Allergic angioedema, typically with urticaria/itch, that responds to epinephrine, antihistamines, and steroids.", more: "Mast-cell histamine release increases vascular permeability — the one angioedema subtype for which the anaphylaxis protocol works." },
  { term: "ACE-inhibitor–induced angioedema", keys: ["ACE-inhibitor–induced angioedema"], def: "Bradykinin-mediated swelling from reduced bradykinin breakdown, occurring at any time after starting the drug — even years later.", more: "Definitive treatment is permanent discontinuation of the ACE inhibitor; epinephrine, antihistamines, and steroids are unreliable, and trial evidence for icatibant/C1-INH in this setting is inconsistent." },
  { term: "Hereditary angioedema (HAE)", keys: ["Hereditary angioedema (HAE)", "Hereditary angioedema", "HAE"], def: "Recurrent bradykinin-mediated angioedema from C1-esterase inhibitor deficiency/dysfunction, with attacks since adolescence, positive family history, and no urticaria.", more: "Loss of C1-INH lets the contact/kallikrein-kinin system generate excess bradykinin; abdominal attacks from bowel-wall edema can mimic a surgical abdomen." },
  { term: "C1-esterase inhibitor (C1-INH)", keys: ["C1-esterase inhibitor (C1-INH)", "C1-esterase inhibitor", "C1-INH"], def: "Regulatory protein that restrains the kallikrein-kinin (contact) system and complement; its deficiency underlies HAE.", more: "Without it, unchecked kallikrein cleaves kininogen to bradykinin, the shared final mediator with ACE-inhibitor angioedema." },
  { term: "Bradykinin-pathway agents", keys: ["Bradykinin-pathway agents"], def: "Targeted HAE therapies: C1-inhibitor concentrate, icatibant (B2-receptor antagonist), and ecallantide (kallikrein inhibitor).", more: "These treat acute bradykinin-mediated attacks; epinephrine/antihistamines/steroids do not, though airway vigilance remains paramount because laryngeal attacks can fully obstruct." },
  { term: "Inhalational/thermal airway injury", keys: ["Inhalational/thermal airway injury"], def: "Progressive supraglottic and glottic edema after flame, steam, or hot-gas exposure that can look reassuring initially.", more: "Intubate early and electively — before stridor/drooling appear — because once late signs develop, edema may make intubation impossible." },
  { term: "Carbonaceous sputum", keys: ["Carbonaceous sputum"], def: "Soot-containing sputum indicating smoke inhalation.", more: "Together with facial burns, singed nasal hair, or new hoarseness after a closed-space fire, any single finding should trigger urgent airway evaluation rather than observation." },
  { term: "Penetrating neck trauma", keys: ["Penetrating neck trauma"], def: "hard signs — Findings mandating immediate operative exploration: expanding/pulsatile hematoma, active pulsatile bleeding, absent distal pulse, air bubbling from the wound, or a new focal neurologic deficit.", more: "Hard signs go to the OR regardless of zone and regardless of a currently stable blood pressure; \"stable now\" is not \"safe to image first.\"" },
  { term: "\"No-zone\" approach", keys: ["No-zone approach"], def: "Contemporary paradigm managing the stable penetrating-neck-trauma patient by physical exam plus CT angiography rather than by entry-wound zone.", more: "Entry zone poorly predicts the trajectory and internal injury, so CTA now guides selective work-up and reduces negative neck explorations." },
  { term: "Neck Zone I", keys: ["Neck Zone I"], def: "Region from the cricoid cartilage to the clavicles/thoracic outlet, containing great-vessel origins, trachea, esophagus, and lung apex.", more: "Least surgically accessible — proximal vascular control may need sternotomy/thoracotomy, so even some hard-sign patients get imaging first when stable enough." },
  { term: "Neck Zone II", keys: ["Neck Zone II"], def: "Region from the cricoid to the angle of the mandible, containing the carotids, jugulars, larynx, trachea, and esophagus.", more: "The largest and most surgically accessible zone and the site of most penetrating neck injuries; hard signs here typically go directly to the OR." },
  { term: "Neck Zone III", keys: ["Neck Zone III"], def: "Region from the angle of the mandible to the skull base, containing distal carotid/vertebral arteries and lower cranial nerves.", more: "Proximal control is difficult, so injuries here may require endovascular (IR) management rather than open exploration." },
  { term: "Danger space", keys: ["Danger space"], def: "Potential space between the alar and prevertebral fascia extending from the skull base to the diaphragm/posterior mediastinum.", more: "It is the anatomic conduit by which a retropharyngeal infection descends to cause necrotizing mediastinitis." },
  { term: "Retropharyngeal abscess", keys: ["Retropharyngeal abscess"], def: "Deep-space collection behind the pharynx, classically in young children with fever, neck stiffness/torticollis, and refusal to move the neck.", more: "Contrast-enhanced neck CT defines the collection and its relation to great vessels/mediastinum before drainage." },
  { term: "Descending necrotizing mediastinitis", keys: ["Descending necrotizing mediastinitis"], def: "Life-threatening spread of oropharyngeal/deep-neck infection into the mediastinum along fascial planes.", more: "Mortality rises steeply once mediastinitis occurs (reported ~17.5–50%), underscoring early source control." },
  { term: "Stridor", keys: ["Stridor"], def: "High-pitched noise from turbulent airflow through a narrowed airway. Timing localizes the level: inspiratory suggests extrathoracic/laryngeal, expiratory suggests intrathoracic, and biphasic suggests fixed subglottic/tracheal narrowing.", more: "It becomes audible once the airway lumen is critically narrowed (roughly ≤50% in adults), so stridor at rest signals advanced obstruction requiring urgent assessment. Because resistance rises with the fourth power of the radius, a small absolute reduction in an already small-caliber airway causes disproportionate obstruction — why children decompensate faster than adults." },
  { term: "Post-tonsillectomy hemorrhage", keys: ["Post-tonsillectomy hemorrhage"], def: "Bleeding after tonsillectomy, classified as primary (<24 h, technical) or secondary (classically post-op days 5–10, when the eschar sloughs); always evaluated urgently regardless of apparent severity.", more: "Swallowed blood underestimates true loss in a small child, and a small \"herald\" bleed can precede catastrophic hemorrhage — there is no \"wait and see.\"" },
  { term: "Airway foreign body", keys: ["Airway foreign body"], def: "Aspirated object causing choking, unilateral wheeze, stridor, or decreased breath sounds, classically in a young child; a right mainstem lodgment is most common given the more vertical right bronchus.", more: "A witnessed choking episode with apparent recovery — or a normal chest film — does not exclude it, since objects migrate and cause delayed complications; rigid bronchoscopy is both diagnostic and therapeutic." },
  { term: "Epiglottitis (supraglottitis)", keys: ["Epiglottitis (supraglottitis)", "supraglottitis", "Epiglottitis"], def: "Inflammation of the epiglottis and supraglottic structures causing rapid airway compromise; presents with sore throat, muffled voice, drooling, and a deceptively normal-looking oropharynx (historically Haemophilus influenzae type b in children, now rarer post-vaccine).", more: "Sore throat (~79%) and dysphagia (~71%) are the commonest symptoms, while stridor (~3.6%) and dyspnea (~6.7%) are less common but predict need for airway intervention. In a child, this means tripod positioning and drooling — do not examine the throat or agitate the patient; secure the airway in a controlled setting first." },
  { term: "House-Brackmann scale", keys: ["House-Brackmann scale"], def: "Grades facial nerve function from I (normal) to VI (total paralysis); used to document and track facial nerve status before and after otologic, skull-base, or parotid surgery, and to follow recovery after facial palsy.", more: "Grade III is the threshold for clinically evident weakness with complete eye closure on effort. Incomplete palsy (retaining some movement) carries an excellent prognosis, whereas complete paralysis with no return by 3 weeks predicts poorer recovery." },

  /* ---- Foundations: cranial nerves, skull base, and general ENT anatomy
     added for the Foundations content pass -- kept short since the full
     per-nerve detail already lives in the Cranial nerves table itself. ---- */
  { term: "Olfactory nerve (CN I)", keys: ["Olfactory nerve (CN I)", "Olfactory nerve"], def: "Sensory nerve for smell; its fibers pass through the cribriform plate to the olfactory bulb.", more: "an anterior skull-base fracture through the cribriform plate can shear these fibers, causing anosmia -- often permanent." },
  { term: "Oculomotor nerve (CN III)", keys: ["Oculomotor nerve (CN III)", "Oculomotor nerve"], def: "Motor nerve to the superior, inferior, and medial rectus, inferior oblique, and levator palpebrae superioris, plus parasympathetic fibers to the pupil.", more: "a compressive lesion (e.g. a posterior communicating artery aneurysm) classically causes a \"surgical\" palsy with a blown, fixed pupil, since the superficial parasympathetic fibers are compressed first; a \"medical\" (ischemic/diabetic) palsy tends to spare the pupil." },
  { term: "Trochlear nerve (CN IV)", keys: ["Trochlear nerve (CN IV)", "Trochlear nerve"], def: "Motor nerve to the superior oblique muscle, which depresses and intorts the eye.", more: "injury causes vertical diplopia worse on downgaze (e.g. reading or descending stairs), often with a compensatory head tilt away from the affected side." },
  { term: "Trigeminal nerve (CN V)", keys: ["Trigeminal nerve (CN V)", "Trigeminal nerve"], def: "The great sensory nerve of the face, in three divisions: V1 (ophthalmic, forehead/cornea), V2 (maxillary, midface/upper teeth), and V3 (mandibular, lower face/tongue plus the motor supply to the muscles of mastication).", more: "V3 is the only division carrying a motor root; loss of the corneal reflex (V1 afferent) is an early, subtle sign of a cerebellopontine-angle lesion like vestibular schwannoma." },
  { term: "Abducens nerve (CN VI)", keys: ["Abducens nerve (CN VI)", "Abducens nerve"], def: "Motor nerve to the lateral rectus, which abducts the eye.", more: "its long intracranial course makes it especially vulnerable to raised intracranial pressure, so a CN VI palsy can be a nonspecific/false-localizing sign of elevated ICP rather than a direct nerve lesion." },
  { term: "Vestibulocochlear nerve (CN VIII)", keys: ["Vestibulocochlear nerve (CN VIII)", "Vestibulocochlear nerve"], def: "Carries hearing (cochlear division) and balance (vestibular division) signals from the inner ear to the brainstem, traveling through the internal acoustic meatus.", more: "an asymmetric sensorineural hearing loss or unilateral tinnitus should prompt an MRI of the internal auditory canals to exclude a vestibular schwannoma arising from this nerve." },
  { term: "Glossopharyngeal nerve (CN IX)", keys: ["Glossopharyngeal nerve (CN IX)", "Glossopharyngeal nerve"], def: "Supplies the stylopharyngeus muscle, sensation and taste to the posterior third of the tongue, pharyngeal sensation (the afferent limb of the gag reflex), and parasympathetic secretomotor fibers to the parotid gland.", more: "glossopharyngeal neuralgia causes brief, severe throat/ear pain triggered by swallowing or talking -- easily mistaken for other causes of otalgia or sore throat." },
  { term: "Vagus nerve (CN X)", keys: ["Vagus nerve (CN X)", "Vagus nerve"], def: "Supplies motor and sensory innervation to the pharynx and larynx (via the pharyngeal and recurrent laryngeal branches) and carries parasympathetic fibers to the thorax and abdomen.", more: "its recurrent laryngeal branch's long, asymmetric course (looping under the aortic arch on the left, the subclavian artery on the right) is why thoracic, thyroid, and mediastinal disease can present as hoarseness." },
  { term: "Accessory nerve (CN XI)", keys: ["Accessory nerve (CN XI)", "Accessory nerve", "Spinal accessory nerve"], def: "Motor nerve to trapezius and sternocleidomastoid.", more: "it runs superficially through the posterior triangle (neck level V), making it the nerve most often injured during neck dissection -- injury causes shoulder droop and a weak shrug from trapezius palsy." },
  { term: "Hypoglossal nerve (CN XII)", keys: ["Hypoglossal nerve (CN XII)", "Hypoglossal nerve"], def: "Motor nerve to the intrinsic and most extrinsic tongue muscles.", more: "on a peripheral (LMN) injury, the protruded tongue deviates toward the weak side (the unopposed genioglossus on the healthy side pushes it over)." },
  { term: "Jugular foramen", keys: ["Jugular foramen"], def: "Skull-base opening transmitting cranial nerves IX, X, and XI, plus the internal jugular vein.", more: "a jugular foramen syndrome (lower cranial neuropathies from a mass here, e.g. glomus jugulare or schwannoma) causes hoarseness, dysphagia, and shoulder weakness together." },
  { term: "Internal acoustic meatus", keys: ["Internal acoustic meatus", "Internal auditory canal", "Internal auditory meatus"], def: "Canal through the petrous temporal bone carrying CN VII and CN VIII (plus the labyrinthine artery) from the brainstem to the inner ear.", more: "vestibular schwannoma classically arises from the vestibular division of CN VIII within this canal, and MRI of the internal auditory canals with contrast is the diagnostic study." },
  { term: "Optic canal", keys: ["Optic canal"], def: "Skull-base canal transmitting the optic nerve (CN II) and ophthalmic artery from the orbit to the cranial cavity.", more: "traumatic or compressive optic-canal injury causes progressive monocular vision loss and is a surgical emergency (optic nerve decompression) in selected cases." },
  { term: "Cribriform plate", keys: ["Cribriform plate"], def: "Perforated portion of the ethmoid bone forming the nasal cavity roof and floor of the anterior cranial fossa, transmitting olfactory nerve (CN I) fibers.", more: "it is thin and easily fractured, the classic route for a CSF leak (and anosmia) after facial or skull-base trauma, or for tumor to breach into the anterior cranial fossa (e.g. esthesioneuroblastoma)." },
  { term: "Meatuses", keys: ["Meatuses", "Meatus"], def: "The grooves on the lateral nasal wall beneath each turbinate. The inferior meatus receives the nasolacrimal duct; the middle meatus houses the ostiomeatal complex (frontal, anterior ethmoid, and maxillary sinus drainage); the superior meatus receives posterior ethmoid drainage.", more: "the sphenoid sinus is the exception -- it drains via the sphenoethmoidal recess above the superior turbinate, not into any of the three meatuses." },
  { term: "Middle meatus", keys: ["Middle meatus"], def: "The groove beneath the middle turbinate; houses the ostiomeatal complex, the shared drainage pathway for the frontal, anterior ethmoid, and maxillary sinuses.", more: "obstruction here is the final common pathway for most rhinosinusitis, regardless of which of the three sinuses started it." },
  { term: "Frontal recess", keys: ["Frontal recess"], def: "The hourglass-shaped drainage pathway connecting the frontal sinus to the middle meatus, bounded by the agger nasi cell anteriorly and the ethmoid bulla posteriorly.", more: "it is one of the most anatomically variable and surgically challenging areas in FESS -- narrow and easily scarred shut by aggressive instrumentation, causing iatrogenic frontal sinusitis." },
  { term: "Nasal septum", keys: ["Nasal septum"], def: "The midline cartilage (quadrangular cartilage anteriorly) and bone (perpendicular plate of ethmoid, vomer posteriorly) partition dividing the nasal cavity into two passages.", more: "a deviated septum can obstruct one side and impair sinus drainage on that side; septal cartilage has no independent blood supply of its own, relying entirely on its perichondrium -- which is exactly why an undrained septal hematoma causes necrosis." },
  { term: "Salivary glands", keys: ["Salivary glands"], def: "Three paired major glands (parotid, submandibular, sublingual) plus hundreds of minor glands throughout the oral mucosa, producing saliva for digestion, lubrication, and antimicrobial defense.", more: "the parotid is the largest but least commonly involved by stones (mostly mucous, low-flow submandibular saliva forms stones more often); the parotid is the most common site of both benign and malignant salivary tumors." },
  { term: "Epiglottis", keys: ["Epiglottis"], def: "The leaf-shaped elastic cartilage at the laryngeal inlet that folds down to protect the airway during swallowing.", more: "a swollen, \"cherry-red\" epiglottis on lateral neck X-ray (the \"thumb sign\") is the classic finding in epiglottitis -- but the diagnosis is clinical, and imaging should never delay securing the airway." },
  { term: "Cricoid cartilage", keys: ["Cricoid cartilage"], def: "The only complete cartilage ring in the airway, sitting below the thyroid cartilage; the narrowest point of the pediatric airway.", more: "it is the landmark for cricothyrotomy (through the cricothyroid membrane just above it) and for cricoid pressure during rapid-sequence intubation." },
  { term: "Thyroid cartilage", keys: ["Thyroid cartilage"], def: "The largest laryngeal cartilage, forming the laryngeal prominence (Adam's apple) and the anterior/lateral framework the vocal folds attach to.", more: "it is unpaired, unlike the arytenoid, corniculate, and cuneiform cartilages, and is the landmark for a thyroplasty (medializing a paralyzed vocal fold via a window cut in its lamina)." },
  { term: "False vocal folds", keys: ["False vocal folds", "Vestibular folds", "Ventricular folds"], def: "The mucosal folds sitting above the true vocal folds, separated from them by the laryngeal ventricle; they protect the airway on swallowing/straining but don't normally vibrate for voice.", more: "\"false cord\" or dysphonic plica ventricularis phonation happens when these folds compensate for weak true-fold closure, producing a rough, strained voice quality." },
  { term: "Sternocleidomastoid", keys: ["Sternocleidomastoid"], def: "The paired strap muscle running from the mastoid process to the sternum and clavicle, dividing the neck into anterior and posterior triangles; innervated by the accessory nerve (CN XI).", more: "it is the key surgical landmark for exposing the carotid sheath, and congenital torticollis (fibrosis/shortening of this muscle) presents as a palpable neonatal neck mass with head tilt." },
  { term: "Thyroid gland", keys: ["Thyroid gland"], def: "A midline, butterfly-shaped endocrine gland overlying the 2nd-4th tracheal rings; the classic reason a midline neck mass that moves with swallowing points here.", more: "the recurrent laryngeal nerve runs immediately posterior to it (at risk in thyroidectomy), and the parathyroid glands sit on its posterior surface." },
  { term: "Nasopharynx", keys: ["Nasopharynx"], def: "The uppermost part of the pharynx, from the skull base to the soft palate; home to the adenoid and the Eustachian tube orifice.", more: "in an adult, a unilateral middle-ear effusion with no other cause should prompt nasopharyngoscopy to exclude a nasopharyngeal mass obstructing the Eustachian tube." },
  { term: "Anterior ethmoidal artery", keys: ["Anterior ethmoidal artery"], def: "A branch of the ophthalmic artery (itself from the internal carotid) that supplies the anterior-superior nasal septum and lateral wall, and contributes to Kiesselbach's plexus.", more: "it is a major source of severe epistaxis when Kiesselbach's-plexus measures fail, and because it's an internal-carotid branch it isn't reachable by transnasal arterial ligation/embolization -- it needs a different surgical approach (endoscopic clipping)." },
  { term: "Ethmoid air cells", keys: ["Ethmoid air cells"], def: "A honeycomb of thin-walled air cells within the ethmoid bone, divided into anterior cells (draining to the middle meatus) and posterior cells (draining to the superior meatus).", more: "they are separated from the orbit by only the paper-thin lamina papyracea and from the anterior cranial fossa by the thin fovea ethmoidalis/cribriform plate -- the anatomic basis for orbital and intracranial complications of ethmoiditis." },
  { term: "Sphenoid sinus", keys: ["Sphenoid sinus"], def: "The most posterior paranasal sinus, sitting below the pituitary fossa (sella turcica) and flanked by the optic nerve, internal carotid artery, and cavernous sinus.", more: "its central skull-base location makes it both the highest-stakes sinus surgically and the standard route for endoscopic transsphenoidal pituitary surgery." },
  { term: "Embolization", keys: ["Embolization"], def: "An interventional-radiology procedure that occludes a feeding blood vessel (via catheter-delivered particles, coils, or glue) to control bleeding or devascularize a tumor before surgery.", more: "it is used for posterior epistaxis refractory to packing and cautery, and preoperatively for highly vascular tumors like juvenile nasopharyngeal angiofibroma, where a direct biopsy would risk severe hemorrhage." },
  { term: "Thyroplasty", keys: ["Thyroplasty"], def: "A laryngeal framework surgery that alters vocal-fold position (most often medializing a paralyzed fold) by placing an implant through a window cut in the thyroid cartilage.", more: "type I thyroplasty (medialization) is the standard surgical treatment for symptomatic unilateral vocal-fold paralysis, done under local anesthesia so the surgeon can fine-tune voice quality while the patient phonates intraoperatively." },
];
